create function pg_temp.effective_contract_occupancy(p jsonb,class_key text) returns jsonb language plpgsql as $fn$
declare r jsonb:=dashboard_private.resolve_legacy_effective_schedule_v1(p);a text:=r#>>'{values,startTime}';b text:=r#>>'{values,endTime}';
begin
 if r->>'kind'='cancelled' then return null;end if;
 return jsonb_build_object('id',p#>>'{session,id}','classId',class_key,'date',r->>'date','state',r->>'state',
 'scope','all','startMinute',case when a is not null and not (r->'errors' ? 'invalid_time_range') then split_part(a,':',1)::int*60+split_part(a,':',2)::int end,
 'endMinute',case when b is not null and not (r->'errors' ? 'invalid_time_range') then split_part(b,':',1)::int*60+split_part(b,':',2)::int end,
