select is(dashboard_private.resolve_legacy_effective_schedule_v1(f->'candidate')->>'kind','resolved','current target candidate resolves: '||(f->>'name')) from effective_incidents;
select is((select count(*)::int from jsonb_array_elements(f->'existing') b where dashboard_private.resolve_legacy_effective_schedule_v1(b)->>'kind'='unresolved'),(f->>'expected_unresolved')::int,'only genuinely missing basics remain unresolved: '||(f->>'name')) from effective_incidents;
select ok(not exists(select 1 from jsonb_array_elements(f->'existing') b where
 case when dashboard_private.resolve_legacy_effective_schedule_v1(b)->>'kind'='resolved'
 then dashboard_private.timetable_intersects_v1(pg_temp.effective_contract_occupancy(f->'candidate','requested'),pg_temp.effective_contract_occupancy(b,'existing'))
 else dashboard_private.timetable_blocker_intersects_v2(pg_temp.effective_contract_occupancy(f->'candidate','requested'),pg_temp.effective_contract_occupancy(b,'existing')) end),
 'unchanged real predicates do not falsely block incident shape: '||(f->>'name')) from effective_incidents;
-- Positive controls: resolution must not disable any collision predicate.
create temp table effective_collision_controls as
select pg_temp.effective_contract_occupancy(f->'candidate','requested') candidate from effective_incidents where f->>'name'='ohyun1a-1002';
select ok(dashboard_private.timetable_intersects_v1(candidate,candidate||'{"id":"other-room","classId":"different","teacherId":"teacher-a"}'::jsonb),'known same-room conflict remains rejected by real predicate') from effective_collision_controls;
select ok(dashboard_private.timetable_intersects_v1(candidate,candidate||'{"id":"other-teacher","classId":"different","classroomId":"room-a"}'::jsonb),'known same-teacher conflict remains rejected by real predicate') from effective_collision_controls;
select ok(dashboard_private.timetable_blocker_intersects_v2(candidate,candidate||'{"id":"missing-room","classId":"different","teacherId":"teacher-a","classroomId":null,"scope":"all"}'::jsonb),'genuinely missing basic room still blocks overlapping occupancy') from effective_collision_controls;
select ok(dashboard_private.timetable_blocker_intersects_v2(candidate,candidate||'{"id":"cleared-teacher","classId":"different","teacherId":null,"classroomId":"room-a","scope":"all"}'::jsonb),'explicitly cleared teacher still blocks overlapping occupancy') from effective_collision_controls;
select ok(not dashboard_private.timetable_intersects_v1(candidate,candidate||'{"id":"adjacent","startMinute":1200,"endMinute":1290}'::jsonb),'known adjacent lessons do not overlap at a shared endpoint') from effective_collision_controls;
select ok(dashboard_private.timetable_blocker_intersects_v2(candidate||'{"teacherId":"teacher-a"}'::jsonb,pg_temp.effective_contract_occupancy(f->'input','different')),'invalid interval retains unknown bounds and cannot evade real blocker predicate') from effective_collision_controls cross join effective_contract_fixtures where f->>'name'='known invalid override interval stays invalid';

