select (f#>>'{request,id}')::uuid,'approval_pending','cancel_makeup','영어','english',pg_temp.eid(901),(f#>>'{request,class_id}')::uuid,f#>>'{request,class_name}',(f#>>'{teacher,id}')::uuid,
case when f#>>'{teacher,id}'=pg_temp.eid(1)::text then pg_temp.eid(901) else null end,pg_temp.eid(1),pg_temp.eid(901),(f#>>'{request,cancel_date}')::date,(f#>>'{request,makeup_start_at}')::timestamptz,(f#>>'{request,makeup_end_at}')::timestamptz,f#>>'{room,name}',f#>'{request,makeup_slots}' from effective_approval_fixtures;
-- 25 dated ordinary rows, 14 earlier same-day rows, one genuinely missing room.
insert into public.classes(id,name,subject,schedule_storage_mode,status,teacher,room,schedule,schedule_plan)
select pg_temp.eid(300+n),'Inherited historical row '||n,'영어','legacy','개강 준비','Inheritance teacher 2',
case when n=40 then '미정' else 'Inheritance room 12' end,
case when n<=25 then '수 15:30-17:00' when n<40 then '토 14:00-15:30' else '토 16:30-18:00' end,
jsonb_build_object('sessions',jsonb_build_array(jsonb_build_object('id','history-'||n,'date',case when n<=25 then '2026-10-02' else '2026-10-03' end,
'scheduleState',case when n=40 then 'makeup' else 'active' end,'isForced',false,'teacherNote','Synthetic retained content')))
from generate_series(1,40) n;
-- Setup only: preexisting overlap/unknown history is not the operation tested.
update dashboard_private.timetable_operating_write_baselines set reference=dashboard_private.read_timetable_operating_reference_v1() where transaction_id=txid_current();
set constraints all immediate;set constraints all deferred;
select set_config('request.jwt.claim.sub',pg_temp.eid(901)::text,true);
select set_config('request.jwt.claim.role','service_role',true);
create function pg_temp.effective_approve(n int,key_number int) returns jsonb language plpgsql as $$
declare result jsonb; detail text; error_context text;
begin
select public.transition_makeup_request_v2((f#>>'{request,id}')::uuid,'approve',f->'patch','approval_pending',pg_temp.eid(key_number)) into result from effective_approval_fixtures where (f->>'n')::int=n;
return result;
exception when others then
 get stacked diagnostics detail=pg_exception_detail,error_context=pg_exception_context;
 raise notice 'EFFECTIVE_APPROVAL_FAILURE n=% code=% message=% detail=% context=%',n,sqlstate,sqlerrm,detail,error_context;
 raise;
end $$;
create function pg_temp.effective_cancel(n int,key_number int) returns jsonb language sql as $$
select public.transition_makeup_request_v2((f#>>'{request,id}')::uuid,'approval_canceled','{"note":"Synthetic cancellation"}','completed',pg_temp.eid(key_number)) from effective_approval_fixtures where (f->>'n')::int=n
$$;
grant select on effective_approval_fixtures to service_role;
create temp table effective_before as select (select count(*) from dashboard_private.notification_deliveries) deliveries;
set local role service_role;
