select is((select count(*)::int from jsonb_array_elements(dashboard_private.read_timetable_operating_reference_v1()->'datedUnresolvedOccupancies') b where b->>'classId' in(select pg_temp.eid(300+n)::text from generate_series(1,40)n)),0,'an unassigned basic room does not leave unresolved rows across forty history rows');
select is((select b->>'endMinute' from jsonb_array_elements(dashboard_private.read_timetable_operating_reference_v1()->'datedSessions') b where b->>'classId'=pg_temp.eid(340)::text),'1080','unassigned room retains known 18:00 endpoint');
select is((select (dashboard_private.legacy_effective_context_v1(c)#>>'{approvedByIdentity,historical-approved-makeup,approvedOverrideVerified}')::boolean from public.classes c where id=pg_temp.eid(205)),true,'approved event, calendar, slot, teacher and after-row binding are verified by real adapter');

