 dashboard_private.legacy_effective_input_v1(c.schedule_plan,v,dashboard_private.legacy_effective_context_v1(c),1,1))->>'kind'
 from public.classes c cross join lateral jsonb_array_elements(c.schedule_plan->'sessions') v
 where c.id=pg_temp.eid(205) and v->>'id'='historical-approved-makeup'),'unresolved',
 'verified approval cannot turn an invalid room name into a valid unassigned room');
