select is((select count(*)::int from dashboard_private.timetable_effective_date_v1(dashboard_private.read_timetable_operating_reference_v1(),'2026-10-16') x where x->>'classId'=pg_temp.eid(206)::text),0,'midnight endpoint creates no next-day lesson');
savepoint tampered_source;
update public.academic_events set note='[[TIPS_MAKEUP]] {}' where id=(select makeup_academic_event_id from public.makeup_requests where id=pg_temp.eid(105));
select is((select (dashboard_private.legacy_effective_context_v1(c)#>>'{approvedByIdentity,historical-approved-makeup,approvedOverrideVerified}')::boolean from public.classes c where id=pg_temp.eid(205)),false,'missing calendar proof leaves source unverified');
