-- Real same-room/teacher overlaps remain errors; failed approval is atomic.
savepoint effective_conflict;
insert into public.classes(id,name,subject,status,schedule_storage_mode,schedule_plan)
values(pg_temp.eid(401),'Synthetic genuine dated conflict','영어','개강 준비','legacy',jsonb_build_object('sessions',jsonb_build_array(jsonb_build_object('id','true-conflict','date','2026-10-15','scheduleState','active','startTime','15:00','endTime','17:00','teacherCatalogId',pg_temp.eid(2),'classroomCatalogId',pg_temp.eid(11)))));
update dashboard_private.timetable_operating_write_baselines set reference=dashboard_private.read_timetable_operating_reference_v1() where transaction_id=txid_current();
set constraints all immediate;set constraints all deferred;
set local role service_role;
select throws_ok('select pg_temp.effective_approve(1,2401)','23P01','timetable_resource_conflict','true dated room conflict still blocks actual approval');
reset role;
select is((select status from public.makeup_requests where id=pg_temp.eid(101)),'approval_pending','failed true conflict leaves request pending');
select is((select schedule_plan from public.classes where id=pg_temp.eid(201)),(select f->'plan' from effective_approval_fixtures where f->>'n'='1'),'failed conflict leaves complete raw plan unchanged');
rollback to effective_conflict;

set local role service_role;
select lives_ok(format('select pg_temp.effective_approve(%s,%s)',n,2100+n),'current pending target shape approves through real reader/guard: '||n) from generate_series(1,4)n;
reset role;
set constraints all immediate;set constraints all deferred;
select is((select schedule_plan from public.classes where id=(f#>>'{request,class_id}')::uuid),f->'after','exact producer plan preserved for current target shape '||(f->>'n')) from effective_approval_fixtures where (f->>'n')::int<=4;
select is((select count(*)::int from dashboard_private.timetable_effective_date_v1(dashboard_private.read_timetable_operating_reference_v1(),(f#>>'{request,cancel_date}')::date) s where s->>'classId'=f#>>'{request,class_id}'),0,'cancelled original has no occupancy for target '||(f->>'n')) from effective_approval_fixtures where (f->>'n')::int<=4;
create temp table effective_after_counts as select (select count(*) from public.academic_events) calendars,(select count(*) from public.makeup_request_events) events;
set local role service_role;
select lives_ok('select pg_temp.effective_approve(4,2104)','same approval key replays after inherited occupancy approval');
reset role;
select is((select count(*) from public.academic_events),(select calendars from effective_after_counts),'replay does not duplicate calendar effects');
select is((select count(*) from public.makeup_request_events),(select events from effective_after_counts),'replay does not duplicate approval events');
set local role service_role;
select lives_ok(format('select pg_temp.effective_cancel(%s,%s)',n,2200+n),'actual cancellation restores raw snapshot for target '||n) from generate_series(1,6)n;
reset role;
set constraints all immediate;set constraints all deferred;
select is((select schedule_plan from public.classes where id=(f#>>'{request,class_id}')::uuid),f->'plan','cancellation restores byte-exact absent/explicit/content state '||(f->>'n')) from effective_approval_fixtures;
select is((select count(*) from dashboard_private.notification_deliveries),(select deliveries from effective_before),'inheritance approvals and cancellations dispatch no delivery');
select ok(not has_function_privilege('authenticated','dashboard_private.resolve_legacy_effective_schedule_v1(jsonb)','execute'),'pure private resolver grants no client access');
select ok(not has_function_privilege('authenticated','dashboard_private.legacy_effective_context_v1(public.classes,jsonb)','execute'),'source adapter grants no client access');
select ok(not has_function_privilege('anon','dashboard_private.makeup_effective_class_context_v1(jsonb)','execute'),'anonymous user cannot read bounded class occupancy');

