insert into public.classes(id,name,subject,status,schedule_storage_mode,teacher,room,schedule,schedule_plan)
values(pg_temp.eid(460),'Synthetic bound slot','영어','수강','legacy','Inheritance teacher 2','Inheritance room 12','월 06:00-07:00; 월 08:00-09:00','{}');
update public.classes c set schedule_plan=jsonb_build_object('sessions',jsonb_build_array(jsonb_build_object('id','bound-row','date','2050-10-10','scheduleState','active','sourceSlotId',dashboard_private.read_timetable_class_weekly_v2(c)#>>'{shadowSlots,0,id}'))) where id=pg_temp.eid(460);
