select is((select count(*)::int from dashboard_private.timetable_effective_date_v1(dashboard_private.read_timetable_operating_reference_v1(),'2050-10-10') x where x->>'classId'=pg_temp.eid(460)::text),2,'bound dated row replaces precisely its weekly slot without duplication');
